// Zeitfenster für das Lesen der Rückmeldungen: Vorschläge und Kommentare der letzten 7 Tage, Störungsnotizen der letzten 14 Tage.
// Dieser Workflow hat keinen Webhook und keinen Zeitplan: Er läuft nur, wenn ihn jemand in n8n von Hand startet oder Claude ihn über den n8n-Connector (MCP) ausführt.
const iso = t => new Date(t).toISOString().replace(/\.\d{3}Z$/, 'Z');
const jetzt = Date.now();
return [{ json: { jetzt: iso(jetzt), seit7: iso(jetzt - 7 * 864e5), seit14: iso(jetzt - 14 * 864e5) } }];

// Baut aus Vorschlägen, Kommentaren und Störungsnotizen EINE kompakte Liste für das KI-Werkzeug (Claude), das die Rückmeldungen beantwortet.
// Rollen statt Namen: Die Mitgliederliste enthält hier nur ID, Rolle, Typ und Status. Keine Namen, keine E-Mail-Adressen, keine Zugangscodes.
const Z = $('Zeitfenster').first().json;
const liste = (name, pk) => { try { return $(name).all().map(i => i.json).filter(x => x && x[pk] !== undefined && x[pk] !== null); } catch (e) { return []; } };
const V = liste('Vorschläge', 'vorschlag_id'), K = liste('Verlauf', 'id'), A = liste('Aufgaben', 'aufgabe_id'), N = liste('Störungsnotizen', 'notiz_id'), M = liste('Mitglieder', 'mitglied_id');
const rolle = id => { const m = M.find(x => x.mitglied_id === id); return m ? (m.typ === 'agent' ? 'agent' : (m.rolle || 'team')) : 'unbekannt'; };
const kurz = (t, n) => { const s = String(t || '').replace(/\r/g, '').trim(); return s.length > n ? s.slice(0, n - 1) + '…' : s; };
const aufgabe = id => A.find(a => a.aufgabe_id === id) || {};
const E = [];
for (const v of V) E.push({ art: 'vorschlag', zeit: v.geaendert || v.erstellt || '', bereich: v.bereich || 'Sonstiges', rolle: rolle(v.autor), titel: kurz(v.titel, 160), text: kurz(v.text, 1500),
  status: v.status || 'neu', stimmen: Array.isArray(v.stimmen) ? v.stimmen.length : 0, antwort: kurz(v.antwort, 1500), antwort_von_rolle: v.antwort_von ? rolle(v.antwort_von) : '', aufgabe_id: v.aufgabe_id || '', id: v.vorschlag_id });
for (const k of K) {
  if (k.art === 'status') continue;   // Statuswechsel sind keine Rückmeldungen
  const a = aufgabe(k.aufgabe_id);
  E.push({ art: k.art === 'bericht' ? 'bericht' : 'kommentar', zeit: k.erstellt || '', bereich: a.projekt || '', rolle: rolle(k.autor), titel: kurz(a.titel || k.aufgabe_id, 160), text: kurz(k.text, 1500), status: a.status || '', aufgabe_id: k.aufgabe_id, id: String(k.id) });
}
for (const n of N) {
  if (!/^Störung\b/i.test(String(n.titel || ''))) continue;   // die Abfrage holt „St*rung*“, hier die genaue Prüfung
  const bloecke = String(n.inhalt || '').split(/\n(?=### )/);
  E.push({ art: 'stoerung', zeit: n.geaendert || '', bereich: n.projekt || '', rolle: rolle(n.geaendert_von || n.autor), titel: kurz(n.titel, 160), text: kurz(bloecke[bloecke.length - 1], 1500), meldungen: Math.max(0, bloecke.length - 1), status: '', id: n.notiz_id });
}
E.sort((a, b) => String(b.zeit).localeCompare(String(a.zeit)));
const zaehl = f => E.filter(f).length;
const zusammenfassung = { stand: Z.jetzt, vorschlaege_und_kommentare_seit: Z.seit7, stoerungen_seit: Z.seit14,
  vorschlaege_neu: zaehl(e => e.art === 'vorschlag' && e.status === 'neu'), vorschlaege_nachfrage: zaehl(e => e.art === 'vorschlag' && e.status === 'nachfrage'), vorschlaege_gesamt: zaehl(e => e.art === 'vorschlag'),
  kommentare: zaehl(e => e.art === 'kommentar' || e.art === 'bericht'), stoerungen: zaehl(e => e.art === 'stoerung'), eintraege: E.length,
  hinweis: 'Rollen statt Namen (admin, team, dozent, vertrieb, agent). Antworten gehen über agent/feedback.mjs: antworten <id> --status nachfrage|geplant|abgelehnt --text …, kommentar <aufgabe_id> --text …, aenderungen --text …' };
return [{ json: { zusammenfassung, eintraege: E } }];
